import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Navbar, Nav, Form, InputGroup, Badge, Modal, Table, Alert, Spinner, Toast } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';
import AdminPanel from './AdminPanel';
import PaymentModal from './PaymentModal';
import NotificationModal from './NotificationModal';

const API_URL = 'http://localhost:5000/api';

function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [user, setUser] = useState(null);
  const [wishlist, setWishlist] = useState([]);
  const [showLogin, setShowLogin] = useState(false);
  const [showCart, setShowCart] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showWishlist, setShowWishlist] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showOrderConfirmation, setShowOrderConfirmation] = useState(false);
  const [showNotification, setShowNotification] = useState(false);
  const [confirmedOrder, setConfirmedOrder] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [reviewText, setReviewText] = useState('');
  const [reviewRating, setReviewRating] = useState(5);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLogin, setIsLogin] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [loading, setLoading] = useState(true);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [showPromoBanner, setShowPromoBanner] = useState(true);
  const [notificationData, setNotificationData] = useState({
    title: '',
    message: '',
    type: 'success',
    details: null
  });

  const [shippingDetails, setShippingDetails] = useState({
    fullName: '',
    address: '',
    city: '',
    state: '',
    pincode: '',
    phone: '',
    paymentMethod: 'cod'
  });

  const allProducts = [
    { id: 1, name: "Apple AirPods Pro", price: 24999, description: "Active Noise Cancellation", category: "Electronics", image: "https://images.unsplash.com/photo-1588423771073-b8903fbb85b5?w=400", stock: 25, brand: "Apple", rating: 4.8 },
    { id: 2, name: "Sony WH-1000XM5", price: 29999, description: "Industry-leading noise cancellation", category: "Electronics", image: "https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?w=400", stock: 15, brand: "Sony", rating: 4.9 },
    { id: 3, name: "iPhone 15 Pro", price: 134900, description: "A17 Pro chip, 48MP camera", category: "Electronics", image: "https://images.unsplash.com/photo-1696446701796-da61225697cc?w=400", stock: 10, brand: "Apple", rating: 4.9 },
    { id: 4, name: "Nike Air Max", price: 12999, description: "Comfortable running shoes", category: "Clothing", image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=400", stock: 40, brand: "Nike", rating: 4.6 },
    { id: 5, name: "Levi's Jeans", price: 3999, description: "Premium denim jeans", category: "Clothing", image: "https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=400", stock: 50, brand: "Levi's", rating: 4.5 },
    { id: 6, name: "Fossil Gen 6 Watch", price: 22999, description: "Smart watch", category: "Accessories", image: "https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=400", stock: 20, brand: "Fossil", rating: 4.7 },
    { id: 7, name: "Titan Analog Watch", price: 8999, description: "Elegant analog watch", category: "Accessories", image: "https://images.unsplash.com/photo-1522312346375-d1a52e2b99b3?w=400", stock: 30, brand: "Titan", rating: 4.5 },
    { id: 8, name: "MacBook Pro M3", price: 169900, description: "M3 chip", category: "Electronics", image: "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=400", stock: 8, brand: "Apple", rating: 4.9 }
  ];

  useEffect(() => {
    setProducts(allProducts);
    setLoading(false);
    const token = localStorage.getItem('token');
    const userData = JSON.parse(localStorage.getItem('user') || '{}');
    if (token && userData.id) {
      setUser(userData);
    }
  }, []);

  const formatIndianRupee = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  };

  const showMessage = (message) => {
    setToastMessage(message);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 3000);
  };

  const showCustomNotification = (title, message, type = 'success', details = null) => {
    setNotificationData({ title, message, type, details });
    setShowNotification(true);
  };

  const handleLogin = (e) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    
    if (!isLogin) {
      const existingUser = storedUsers.find(u => u.email === email);
      if (existingUser) {
        showCustomNotification('Registration Failed', 'Email already registered!', 'error');
        return;
      }
      const newUser = { id: Date.now(), name, email, password, isAdmin: email === 'pankuchauhan35@gmail.com' };
      localStorage.setItem('app_users', JSON.stringify([...storedUsers, newUser]));
      localStorage.setItem('user', JSON.stringify({ id: newUser.id, name, email, isAdmin: newUser.isAdmin }));
      setUser({ id: newUser.id, name, email, isAdmin: newUser.isAdmin });
      setShowLogin(false);
      showCustomNotification('Welcome!', `Account created successfully! Welcome ${name}!`, 'success');
    } else {
      const foundUser = storedUsers.find(u => u.email === email && u.password === password);
      if (foundUser) {
        localStorage.setItem('user', JSON.stringify({ id: foundUser.id, name: foundUser.name, email, isAdmin: foundUser.isAdmin }));
        setUser({ id: foundUser.id, name: foundUser.name, email, isAdmin: foundUser.isAdmin });
        setShowLogin(false);
        showCustomNotification('Welcome Back!', `Hello ${foundUser.name}, great to see you again!`, 'success');
      } else {
        showCustomNotification('Login Failed', 'Invalid email or password. Please try again.', 'error');
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    setUser(null);
    setCart([]);
    showCustomNotification('Logged Out', 'You have been successfully logged out.', 'info');
  };

  const addToCart = (product) => {
    const existingItem = cart.find(item => item.id === product.id);
    if (existingItem) {
      setCart(cart.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item));
    } else {
      setCart([...cart, { ...product, quantity: 1 }]);
    }
    showCustomNotification('Added to Cart', `${product.name} has been added to your cart!`, 'success', {
      'Price': formatIndianRupee(product.price),
      'Cart Total': formatIndianRupee(getCartTotal() + product.price)
    });
  };

  const removeFromCart = (productId) => {
    setCart(cart.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId, newQuantity) => {
    if (newQuantity < 1) {
      removeFromCart(productId);
    } else {
      setCart(cart.map(item => item.id === productId ? { ...item, quantity: newQuantity } : item));
    }
  };

  const getCartTotal = () => cart.reduce((total, item) => total + (item.price * item.quantity), 0);
  const getCartCount = () => cart.reduce((count, item) => count + item.quantity, 0);

  const handleCheckoutInput = (e) => {
    setShippingDetails({ ...shippingDetails, [e.target.name]: e.target.value });
  };

  const handlePaymentSuccess = () => {
    const orderDetails = {
      orderId: 'ORD' + Date.now(),
      items: cart,
      total: formatIndianRupee(getCartTotal()),
      paymentMethod: 'Online Payment',
      shippingAddress: `${shippingDetails.fullName}, ${shippingDetails.address}, ${shippingDetails.city} - ${shippingDetails.pincode}`,
      date: new Date().toLocaleString()
    };
    
    const orders = JSON.parse(localStorage.getItem('orders') || '[]');
    orders.push(orderDetails);
    localStorage.setItem('orders', JSON.stringify(orders));
    localStorage.removeItem('cart');
    
    setConfirmedOrder(orderDetails);
    setShowOrderConfirmation(true);
    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    setShowCheckout(false);
    
    showCustomNotification('Order Confirmed!', 'Your order has been placed successfully!', 'success', {
      'Order ID': orderDetails.orderId,
      'Total': orderDetails.total,
      'Payment': 'Online Payment',
      'Items': cart.length
    });
  };

  const placeOrder = () => {
    if (!shippingDetails.fullName || !shippingDetails.address || !shippingDetails.city || !shippingDetails.pincode || !shippingDetails.phone) {
      showCustomNotification('Incomplete Details', 'Please fill all shipping details', 'error');
      return;
    }
    
    if (shippingDetails.paymentMethod === 'online') {
      setShowCheckout(false);
      setShowPayment(true);
      return;
    }
    
    const orderDetails = {
      orderId: 'ORD' + Date.now(),
      items: cart,
      total: formatIndianRupee(getCartTotal()),
      paymentMethod: 'Cash on Delivery',
      shippingAddress: `${shippingDetails.fullName}, ${shippingDetails.address}, ${shippingDetails.city} - ${shippingDetails.pincode}`,
      date: new Date().toLocaleString()
    };
    
    const orders = JSON.parse(localStorage.getItem('orders') || '[]');
    orders.push(orderDetails);
    localStorage.setItem('orders', JSON.stringify(orders));
    localStorage.removeItem('cart');
    
    setConfirmedOrder(orderDetails);
    setShowOrderConfirmation(true);
    setCart([]);
    setShowCart(false);
    setShowCheckout(false);
    
    showCustomNotification('Order Confirmed!', 'Your order has been placed successfully!', 'success', {
      'Order ID': orderDetails.orderId,
      'Total': orderDetails.total,
      'Payment': 'Cash on Delivery',
      'Items': cart.length
    });
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const categories = ['All', ...new Set(products.map(p => p.category))];

  if (showAdmin && user?.isAdmin) {
    return <AdminPanel onBack={() => setShowAdmin(false)} />;
  }

  return (
    <div className="app">
      {/* Notification Modal */}
      <NotificationModal 
        show={showNotification}
        onClose={() => setShowNotification(false)}
        title={notificationData.title}
        message={notificationData.message}
        type={notificationData.type}
        details={notificationData.details}
      />

      {/* Toast Notification */}
      <div className="toast-container position-fixed bottom-0 end-0 p-3" style={{ zIndex: 1100 }}>
        <Toast show={showToast} onClose={() => setShowToast(false)} delay={3000} autohide bg="success">
          <Toast.Body className="text-white">{toastMessage}</Toast.Body>
        </Toast>
      </div>

      {/* Payment Modal */}
      <PaymentModal 
        show={showPayment}
        onClose={() => setShowPayment(false)}
        amount={getCartTotal()}
        onSuccess={handlePaymentSuccess}
      />

      {/* Order Confirmation Modal */}
      <Modal show={showOrderConfirmation} onHide={() => setShowOrderConfirmation(false)} centered>
        <Modal.Header closeButton className="bg-success text-white">
          <Modal.Title>🎉 Order Confirmed!</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {confirmedOrder && (
            <>
              <p><strong>Order ID:</strong> {confirmedOrder.orderId}</p>
              <p><strong>Total:</strong> {confirmedOrder.total}</p>
              <p><strong>Payment:</strong> {confirmedOrder.paymentMethod}</p>
              <p><strong>Shipping:</strong> {confirmedOrder.shippingAddress}</p>
              <p><strong>Date:</strong> {confirmedOrder.date}</p>
              <Alert variant="info" className="mt-3">
                <i className="bi bi-truck"></i> Estimated Delivery: 3-5 business days
              </Alert>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="success" onClick={() => setShowOrderConfirmation(false)}>Continue Shopping</Button>
        </Modal.Footer>
      </Modal>

      {/* Navbar */}
      <Navbar bg="dark" variant="dark" expand="lg" sticky="top" className="shadow">
        <Container>
          <Navbar.Brand href="#" className="d-flex align-items-center">
            <i className="bi bi-shop fs-3 me-2"></i>
            <span className="fw-bold fs-4">ShopHub India</span>
          </Navbar.Brand>
          <Navbar.Toggle aria-controls="basic-navbar-nav" />
          <Navbar.Collapse id="basic-navbar-nav">
            <Form className="mx-auto w-50">
              <InputGroup>
                <InputGroup.Text><i className="bi bi-search"></i></InputGroup.Text>
                <Form.Control type="text" placeholder="Search products..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              </InputGroup>
            </Form>
            <Nav className="ms-auto align-items-center gap-2">
              <Button variant="outline-light" onClick={() => setShowCart(true)} className="position-relative">
                <i className="bi bi-cart3"></i> Cart
                {getCartCount() > 0 && <Badge bg="warning" pill className="position-absolute top-0 start-100 translate-middle">{getCartCount()}</Badge>}
              </Button>
              {user ? (
                <div className="d-flex gap-2 align-items-center">
                  <span className="text-light"><i className="bi bi-person-circle"></i> {user.name}</span>
                  {user.isAdmin && <Button variant="info" size="sm" onClick={() => setShowAdmin(true)}><i className="bi bi-speedometer2"></i> Admin</Button>}
                  <Button variant="outline-danger" size="sm" onClick={handleLogout}><i className="bi bi-box-arrow-right"></i></Button>
                </div>
              ) : (
                <Button variant="primary" onClick={() => setShowLogin(true)}><i className="bi bi-person"></i> Login</Button>
              )}
            </Nav>
          </Navbar.Collapse>
        </Container>
      </Navbar>

      {/* Category Filter */}
      <div className="category-bar bg-light py-3 border-bottom shadow-sm">
        <Container>
          <div className="d-flex gap-2 flex-wrap justify-content-center">
            {categories.map(category => (
              <Button key={category} variant={selectedCategory === category ? "primary" : "outline-secondary"} size="sm" onClick={() => setSelectedCategory(category)} className="rounded-pill px-3">{category}</Button>
            ))}
          </div>
        </Container>
      </div>

      {/* Hero Banner */}
      <div className="hero-banner bg-primary text-white py-5 mb-4">
        <Container className="text-center">
          <h1 className="display-4 fw-bold mb-3">Welcome to ShopHub India</h1>
          <p className="lead mb-0">Amazing products at best prices!</p>
        </Container>
      </div>

      {/* Products Grid */}
      <Container className="py-4">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h3><i className="bi bi-grid-3x3-gap-fill me-2"></i>Featured Products</h3>
          <Badge bg="secondary" pill className="fs-6">{filteredProducts.length} products</Badge>
        </div>

        <Row xs={1} sm={2} md={3} lg={4} className="g-4">
          {filteredProducts.map(product => (
            <Col key={product.id}>
              <Card className="h-100 shadow-sm product-card">
                <div className="image-wrapper position-relative">
                  <Card.Img variant="top" src={product.image} className="product-img" />
                  {product.stock < 20 && <Badge bg="warning" className="stock-badge">Only {product.stock} left</Badge>}
                </div>
                <Card.Body className="d-flex flex-column">
                  <Card.Title className="fs-6 fw-bold mb-0">{product.name}</Card.Title>
                  <Badge bg="info" pill className="mb-2">{product.brand}</Badge>
                  <Card.Text className="small text-muted">{product.description}</Card.Text>
                  <div className="rating mb-2">{'★'.repeat(Math.floor(product.rating))}{'☆'.repeat(5 - Math.floor(product.rating))} ({product.rating})</div>
                  <div className="mt-auto d-flex justify-content-between align-items-center">
                    <h5 className="text-primary mb-0 fw-bold">{formatIndianRupee(product.price)}</h5>
                    <Button variant="primary" size="sm" onClick={() => addToCart(product)} className="rounded-pill"><i className="bi bi-cart-plus"></i> Add</Button>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      </Container>

      {/* Cart Modal */}
      <Modal show={showCart} onHide={() => setShowCart(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title><i className="bi bi-cart3 me-2"></i>Your Cart ({getCartCount()} items)</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {cart.length === 0 ? (
            <div className="text-center py-5"><i className="bi bi-emoji-smile fs-1"></i><p className="mt-3">Your cart is empty!</p></div>
          ) : (
            <Table responsive>
              <thead><tr><th>Product</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr></thead>
              <tbody>
                {cart.map(item => (
                  <tr key={item.id}>
                    <td className="align-middle"><div className="d-flex gap-2"><img src={item.image} alt={item.name} style={{ width: '50px', height: '50px', objectFit: 'cover' }} /><span className="fw-bold">{item.name}</span></div></td>
                    <td className="align-middle">{formatIndianRupee(item.price)}</td>
                    <td className="align-middle"><div className="d-flex gap-2"><Button size="sm" variant="outline-secondary" onClick={() => updateQuantity(item.id, item.quantity - 1)}>-</Button><span className="fw-bold">{item.quantity}</span><Button size="sm" variant="outline-secondary" onClick={() => updateQuantity(item.id, item.quantity + 1)}>+</Button></div></td>
                    <td className="align-middle fw-bold">{formatIndianRupee(item.price * item.quantity)}</td>
                    <td className="align-middle"><Button variant="link" className="text-danger" onClick={() => removeFromCart(item.id)}><i className="bi bi-trash"></i></Button></td>
                  </tr>
                ))}
              </tbody>
              <tfoot><tr className="table-active"><td colSpan="3" className="text-end fw-bold">Total:</td><td colSpan="2" className="fw-bold fs-5 text-primary">{formatIndianRupee(getCartTotal())}</td></tr></tfoot>
            </Table>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowCart(false)}>Continue Shopping</Button>
          {cart.length > 0 && <Button variant="success" onClick={() => { setShowCart(false); setShowCheckout(true); }}><i className="bi bi-credit-card"></i> Checkout</Button>}
        </Modal.Footer>
      </Modal>

      {/* Checkout Modal */}
      <Modal show={showCheckout} onHide={() => setShowCheckout(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-success text-white">
          <Modal.Title><i className="bi bi-clipboard-check me-2"></i>Checkout</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Row>
            <Col md={6}>
              <h5>Order Summary</h5>
              <div className="bg-light p-3 rounded">
                {cart.map(item => (<div key={item.id} className="d-flex justify-content-between mb-2"><span>{item.name} x {item.quantity}</span><span>{formatIndianRupee(item.price * item.quantity)}</span></div>))}
                <hr /><div className="d-flex justify-content-between fw-bold"><span>Total:</span><span className="text-success">{formatIndianRupee(getCartTotal())}</span></div>
              </div>
            </Col>
            <Col md={6}>
              <h5>Shipping Details</h5>
              <Form>
                <Form.Control className="mb-2" type="text" name="fullName" placeholder="Full Name" value={shippingDetails.fullName} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="text" name="address" placeholder="Address" value={shippingDetails.address} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="text" name="city" placeholder="City" value={shippingDetails.city} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="text" name="state" placeholder="State" value={shippingDetails.state} onChange={handleCheckoutInput} />
                <Form.Control className="mb-2" type="text" name="pincode" placeholder="PIN Code" value={shippingDetails.pincode} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="tel" name="phone" placeholder="Phone" value={shippingDetails.phone} onChange={handleCheckoutInput} required />
                <Form.Select name="paymentMethod" value={shippingDetails.paymentMethod} onChange={handleCheckoutInput}>
                  <option value="cod">💰 Cash on Delivery</option>
                  <option value="online">💳 Online Payment (UPI / Card)</option>
                </Form.Select>
              </Form>
            </Col>
          </Row>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowCheckout(false)}>Back</Button>
          <Button variant="success" onClick={placeOrder}>Place Order</Button>
        </Modal.Footer>
      </Modal>

      {/* Login Modal */}
      <Modal show={showLogin} onHide={() => setShowLogin(false)} centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title><i className="bi bi-person-circle me-2"></i>{isLogin ? 'Login' : 'Register'}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleLogin}>
            {!isLogin && <Form.Control className="mb-3" type="text" placeholder="Full Name" value={name} onChange={(e) => setName(e.target.value)} required />}
            <Form.Control className="mb-3" type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} required />
            <Form.Control className="mb-3" type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} required />
            <Button type="submit" variant="primary" className="w-100">{isLogin ? 'Login' : 'Register'}</Button>
          </Form>
          <div className="text-center mt-3">
            <Button variant="link" onClick={() => setIsLogin(!isLogin)}>{isLogin ? "New user? Register" : "Existing user? Login"}</Button>
          </div>
          <Alert variant="info" className="mt-3 small">
            <i className="bi bi-shield-lock"></i> Create account to start shopping!
          </Alert>
        </Modal.Body>
      </Modal>

      {/* Footer */}
      <footer className="bg-dark text-white mt-5 py-4">
        <Container>
          <Row>
            <Col md={4}><h5><i className="bi bi-shop"></i> ShopHub India</h5><p className="small">Your one-stop destination for quality products.</p></Col>
            <Col md={4}><h5>Quick Links</h5><ul className="list-unstyled small"><li><a href="#" className="text-white-50">About Us</a></li><li><a href="#" className="text-white-50">Contact</a></li><li><a href="#" className="text-white-50">Returns</a></li></ul></Col>
            <Col md={4}><h5>Contact</h5><p className="small mb-1"><i className="bi bi-envelope"></i> support@shophub.com</p><p className="small"><i className="bi bi-telephone"></i> +91 98765 43210</p></Col>
          </Row>
          <hr /><p className="text-center small mb-0">&copy; 2025 ShopHub India. All rights reserved.</p>
        </Container>
      </footer>
    </div>
  );
}

export default App;
